const units = {
  house: { en: ['house', 'houses'], pl: ['dom', 'domy', 'domów'] },
  planet: { en: ['planet', 'planets'], pl: ['planeta', 'planety', 'planet'] },
  universe: { en: ['Universe', 'Universes'], pl: ['Wszechświat', 'Wszechświaty', 'Wszechświatów'] },
};

export function createLocale(preference) {
  const language = preference === 'pl' ? 'pl' : 'en';
  const numberFormat = new Intl.NumberFormat(language === 'pl' ? 'pl-PL' : 'en-US', {
    maximumFractionDigits: 2,
  });
  const plurals = new Intl.PluralRules(language);
  const format = value => Number.isFinite(value) ? numberFormat.format(value) : '—';

  return {
    language,
    format,
    text: (key, ...args) => {
      const translated = language === 'pl' && Object.hasOwn(PL, key) ? PL[key] : key;
      return args.length ? translated.replace(/\{(\d+)\}/g, (_, index) => args[index]) : translated;
    },
    count: (value, unit) => {
      const category = plurals.select(value);
      const index = category === 'one' ? 0 : (language === 'en' || category === 'few') ? 1 : 2;
      return `${format(value)} ${units[unit][language][index]}`;
    },
  };
}
